+        for (ggml_tensor * w : tensors) {
+            if (w == nullptr || w->buffer == nullptr || !ggml_backend_buffer_is_host(w->buffer)) {
+                continue;
+            }
+
+            const int n_expert = (int) w->ne[2];
+            const int n_slots  = std::min<int64_t>((int64_t) cparams.expert_cache_slots, n_expert - 1);
+            if (n_slots <= 0) {
